// One line per search: keyword | place. The place is optional.
const c = $input.first().json;
return String(c.searches).split('\n').map((l) => l.trim()).filter(Boolean).map((line) => {
  const [query, location] = line.split('|').map((s) => s.trim());
  return { json: { query, location: location ?? '', maxItems: Number(c.maxPerSearch) } };
});

const list = (s) => String(s ?? '').split(',').map((x) => x.trim().toLowerCase()).filter(Boolean);
const c = $('Configuration').first().json;
const exclude = list(c.excludeWords);
const minLoad = Number(c.minWorkload);
const seen = $getWorkflowStaticData('global').seen ?? {};

// The same job is often on jobs.ch and jobup.ch, so the key is title plus company, not the URL.
const keyOf = (r) => `${r.title ?? ''}|${r.company ?? ''}`.toLowerCase().replace(/\s+/g, ' ').trim();
const topLoad = (w) => Math.max(0, ...(String(w ?? '').match(/\d+/g) ?? []).map(Number));

const picked = new Map();
for (const { json: r } of $input.all()) {
  if (!r.url || !r.title) continue;
  const key = keyOf(r);
  if (seen[key] || picked.has(key)) continue;
  if (exclude.some((w) => `${r.title} ${r.company ?? ''}`.toLowerCase().includes(w))) continue;
  const load = topLoad(r.workload);
  if (load && load < minLoad) continue;
  picked.set(key, { key, title: r.title, company: r.company ?? '', location: r.location ?? '',
    workload: r.workload ?? '', board: r.source ?? '', url: r.url });
}
return [...picked.values()].map((json) => ({ json }));

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const jobs = $input.all().map((i) => i.json);
const lis = jobs.map((j) => `<li><a href="${esc(j.url)}">${esc(j.title)}</a><br>` +
  `${esc(j.company)}, ${esc(j.location)} ${esc(j.workload)} (${esc(j.board)})</li>`).join('');
return [{ json: { count: jobs.length, html: `<p>New jobs for your searches: ${jobs.length}</p><ul>${lis}</ul>` } }];

// Runs only after the email was sent, so a failed email does not lose jobs.
const data = $getWorkflowStaticData('global');
const seen = data.seen ?? {};
const today = $now.toFormat('yyyy-MM-dd');
for (const item of $('Drop filtered and already sent jobs').all()) seen[item.json.key] = today;

// Forget jobs after 90 days so the memory stays small.
const cutoff = $now.minus({ days: 90 }).toFormat('yyyy-MM-dd');
for (const [key, date] of Object.entries(seen)) if (date < cutoff) delete seen[key];
data.seen = seen;
return [{ json: { remembered: Object.keys(seen).length } }];
